## Code Example

```python
import time
from typing import List, Dict

def select_modules(risk: str) -> List[str]:
    if risk == "high":
        return ["RedactionGuard","PrivacyGuard"]
    elif risk == "medium":
        return ["PrivacyGuard","LatencyGuard"]
    else:
        return ["LatencyGuard"]

def apply_guards(p: str, modules: List[str]) -> str:
    s = p
    for m in modules:
        if m == "RedactionGuard":
            s = s.replace("SSN", "[REDACTED]")
        if m == "PrivacyGuard":
            s = s.replace("email", "em[REDACTED]")
        if m == "LatencyGuard":
            time.sleep(0.01)  # simulate guard overhead
    return s

def audit(p: str, g: str, modules: List[str], latency: float) -> Dict:
    return {"input": p, "guarded": g, "modules": modules, "latency_ms": int(latency*1000)}
```

